import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long m = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        long maxBananas = 0;

        // Iterate over possible x2 (right boundary of rectangle)
        for (long x2 = 0; x2 <= b * m; x2++) {
            // y2 from line: x/m + y = b => y = b - x/m
            long y2 = b - x2 / m;
            if (y2 < 0) continue;

            // Sum over x from 0..x2 and y from 0..y2 of (x + y)
            // sum_x = (y2+1) * sum_{x=0..x2} x = (y2+1) * x2*(x2+1)/2
            long sumX = (y2 + 1) * x2 * (x2 + 1) / 2;

            // sum_y = (x2+1) * sum_{y=0..y2} y = (x2+1) * y2*(y2+1)/2
            long sumY = (x2 + 1) * y2 * (y2 + 1) / 2;

            long total = sumX + sumY;
            if (total > maxBananas) {
                maxBananas = total;
            }
        }

        System.out.println(maxBananas);
    }
}

