        for (long x2 = 0; x2 <= b * m; x2++) {
            // y2 is determined by the line: x/m + y = b => y = b - x/m
            long y2 = b - x2 / m;
            if (y2 < 0) continue;

            // Sum over x from 0 to x2 of (x + sum over y from 0 to y2 of y)
