            long term1 = (y2 + 1) * sumX;
            long term2 = nX * y2 * (y2 + 1) / 2;
            long total = term1 + term2;

            if (total > maxBananas) {
                maxBananas = total;
            }
        }

        System.out.println(maxBananas);
    }
}

