import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long m = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        long maxBananas = 0;

        // Iterate over possible x2 (right side of rectangle)
        for (long x2 = 0; x2 <= b * m; x2++) {
            // y2 is the maximum integer y such that point (x2, y2) is on or under the line
            long y2 = (b * m - x2) / m;
            if (y2 < 0) continue;

            // Sum over x from 0 to x2 of (x + y2) = sum_x + (x2+1)*y2
            long nX = x2 + 1;
            long sumX = x2 * (x2 + 1) / 2;
            long sumRow = sumX + nX * y2;

            // Now sum over y from 0 to y2 of sumRow
            long nY = y2 + 1;
            long total = sumRow * nY;

            if (total > maxBananas) {
                maxBananas = total;
            }
        }

        System.out.println(maxBananas);
    }
}

