import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        long m = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        long maxBananas = 0;

        // Iterate over all possible integer x-intercepts (x0) from 0 to b*m
        for (long x0 = 0; x0 <= b * m; x0++) {
            // Corresponding y-intercept from line: y = -x/m + b => y0 = b - x0/m
            long y0 = b - x0 / m;

            // Sum over x from 0 to x0 of sum over y from 0 to floor(-x/m + b) of (x + y)
            // For each x, max y is y_max = b - x/m
            long total = 0;
            for (long x = 0; x <= x0; x++) {
                long yMax = b - x / m;
                long countY = yMax + 1; // y from 0 to yMax inclusive

                // Sum of (x + y) for y=0..yMax:
                // = countY * x + (yMax * (yMax + 1)) / 2
                total += countY * x + (yMax * (yMax + 1)) / 2;
            }

            if (total > maxBananas) {
                maxBananas = total;
            }
        }

        System.out.println(maxBananas);
    }
}

