        StringTokenizer st = new StringTokenizer(br.readLine());
        long m = Long.parseLong(st.nextToken());
        long b = Long.parseLong(st.nextToken());

        long maxBananas = 0;

        // Iterate over possible x2 (right boundary of rectangle)
        for (long x2 = 0; x2 <= b * m; x2++) {
            // Maximum y2 such that x2/m + y2 <= b  => y2 <= b - x2/m
            long y2 = b - x2 / m;
            if (y2 < 0) continue;

            // Sum over x from 0 to x2 of sum over y from 0 to y2 of (x + y)
            // = sum_x ( (y2+1)*x + y2*(y2+1)/2 )
            // = (y2+1)*sum_x x + (x2+1)*y2*(y2+1)/2
            long nX = x2 + 1;
            long nY = y2 + 1;

            long sumX = nX * x2 / 2;              // sum_{x=0}^{x2} x
            long sumY = y2 * nY / 2;              // sum_{y=0}^{y2} y

            long total = nY * sumX + nX * sumY;   // total bananas in rectangle

            if (total > maxBananas) {
                maxBananas = total;
            }
        }

        System.out.println(maxBananas);
    }
}

